/* eslint-disable @typescript-eslint/no-explicit-any */
declare module 'canvas-confetti' {
  export interface ConfettiOptions {
    particleCount?: number;
    angle?: number;
    spread?: number;
    startVelocity?: number;
    gravity?: number;
    origin?: { x?: number; y?: number };
    shapes?: any[];
    ticks?: number;
    zIndex?: number;
    scalar?: number;
  }
  export interface ShapeFromTextOptions {
    text: string;
    scalar?: number;
  }
  export interface ConfettiFunction {
    (options?: ConfettiOptions): void;
    shapeFromText: (opts: ShapeFromTextOptions) => any;
  }
  const confetti: ConfettiFunction;
  export default confetti;
}

import type { CapacitorConfig } from '@capacitor/cli';

const config: CapacitorConfig = {
  appId: 'com.super-productivity.app',
  appName: 'Super Productivity',
  webDir: 'dist/browser',
  plugins: {
    CapacitorHttp: {
      enabled: true,
    },
    LocalNotifications: {
      // Android-specific: small icon for notification
      smallIcon: 'ic_stat_sp',
    },
    Keyboard: {
      // Default: resize body (Android)
      resize: 'body',
      resizeOnFullScreen: true,
    },
  },
  android: {
    adjustMarginsForEdgeToEdge: 'auto',
  },
  ios: {
    // Content inset for safe areas (notch, home indicator)
    contentInset: 'never',
    // Background color for safe areas (home indicator, notch)
    // Use dark color to match dark theme (most common on mobile)
    backgroundColor: '#131314',
    // Allow inline media playback
    allowsLinkPreview: true,
    // Scroll behavior
    scrollEnabled: true,
    // iOS-specific plugin overrides
    plugins: {
      StatusBar: {
        overlaysWebView: true,
      },
      Keyboard: {
        // Resize the native WebView when keyboard appears
        // This shrinks the viewport so 100vh/100% automatically fits above keyboard
        resize: 'native',
        resizeOnFullScreen: true,
      },
    },
  },
};

export default config;

